package golang

import "strings"

// Full TS Number closures use binary64's NaN/Infinity values. Pruned portable
// workloads keep their existing finite runtime and generated bytes.
func nonfiniteRuntime(source string) string {
	source = strings.Replace(source, "return dynNumber(d) != 0", "n:=dynNumber(d);return n!=0 && !math.IsNaN(n)", 1)
	source = strings.Replace(source, "func numberString(x float64) jsString {", `func numberString(x float64) jsString {
 if math.IsNaN(x) {return str("NaN")}
 if math.IsInf(x,1) {return str("Infinity")}
 if math.IsInf(x,-1) {return str("-Infinity")}`, 1)
	return source + nonfiniteNumberSource
}

const nonfiniteNumberSource = `
func numberIsNaN(n float64) bool {return math.IsNaN(n)}
func numberTruth(n float64) bool {return n!=0 && !math.IsNaN(n)}
func parseFloatNumber(s jsString) float64 {
 text:=s.trimStart().String()
 if strings.HasPrefix(text,"Infinity") || strings.HasPrefix(text,"+Infinity") {return math.Inf(1)}
 if strings.HasPrefix(text,"-Infinity") {return math.Inf(-1)}
 text=floatPrefix.FindString(text)
 if text=="" {return math.NaN()}
 n,err:=strconv.ParseFloat(text,64)
 if err!=nil && !math.IsInf(n,0) {panic(newTrap("decimal prefix conversion failed"))}
 return n
}
func parseIntNumber(s jsString) float64 {
 text:=s.trimStart().String();sign:=float64(1)
 if strings.HasPrefix(text,"-") {sign=-1;text=text[1:]} else if strings.HasPrefix(text,"+") {text=text[1:]}
 end:=0
 for end<len(text) && text[end]>='0' && text[end]<='9' {end++}
 if end==0 {return math.NaN()}
 n,err:=strconv.ParseFloat(text[:end],64)
 if err!=nil && !math.IsInf(n,0) {panic(newTrap("integer prefix conversion failed"))}
 return sign*n
}
`
